-- psql -X -v ON_ERROR_STOP=1 "$DATABASE_URL" -f scripts/ops/index-assistant-credit-spend.sql
-- Autocommit ONLY; never BEGIN or migration runner. After an interrupted build,
-- DROP INDEX CONCURRENTLY <invalid-name> then rerun; never silently accept it.
SET lock_timeout = '5s';
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS assistant_credit_usage_revision_unique
 ON assistant_credit_ledger(usage_ledger_id,cost_revision) WHERE usage_ledger_id IS NOT NULL AND cost_revision IS NOT NULL;
RESET lock_timeout;
SELECT 1 / count(*)::int AS assistant_credit_usage_revision_unique_ready FROM pg_index i WHERE i.indexrelid=to_regclass('assistant_credit_usage_revision_unique') AND i.indrelid=to_regclass('assistant_credit_ledger') AND i.indisvalid AND i.indisready AND i.indisunique=true AND i.indnkeyatts=2 AND i.indnatts=2 AND i.indexprs IS NULL AND (SELECT array_agg(a.attname::text ORDER BY key.n) FROM unnest(i.indkey) WITH ORDINALITY key(attnum,n) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=key.attnum)=ARRAY['usage_ledger_id','cost_revision']::text[] AND regexp_replace(replace(coalesce(pg_get_expr(i.indpred,i.indrelid),''),'::text',''),'[[:space:]()]','','g')='usage_ledger_idISNOTNULLANDcost_revisionISNOTNULL';
SELECT 1 / count(*)::int AS assistant_credit_turns_held_ready FROM pg_index i WHERE i.indexrelid=to_regclass('assistant_credit_turns_held') AND i.indrelid=to_regclass('assistant_credit_turns') AND i.indisvalid AND i.indisready AND i.indisunique=false AND i.indnkeyatts=1 AND i.indnatts=1 AND i.indexprs IS NULL AND (SELECT array_agg(a.attname::text ORDER BY key.n) FROM unnest(i.indkey) WITH ORDINALITY key(attnum,n) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=key.attnum)=ARRAY['user_id']::text[] AND regexp_replace(replace(coalesce(pg_get_expr(i.indpred,i.indrelid),''),'::text',''),'[[:space:]()]','','g')='held_credits>0';
SELECT 1 / count(*)::int AS assistant_credit_turns_reconcile_ready FROM pg_index i WHERE i.indexrelid=to_regclass('assistant_credit_turns_reconcile') AND i.indrelid=to_regclass('assistant_credit_turns') AND i.indisvalid AND i.indisready AND i.indisunique=false AND i.indnkeyatts=2 AND i.indnatts=2 AND i.indexprs IS NULL AND (SELECT array_agg(a.attname::text ORDER BY key.n) FROM unnest(i.indkey) WITH ORDINALITY key(attnum,n) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=key.attnum)=ARRAY['state','next_reconcile_at']::text[] AND regexp_replace(replace(coalesce(pg_get_expr(i.indpred,i.indrelid),''),'::text',''),'[[:space:]()]','','g')='';
SELECT 1 / count(*)::int AS assistant_credit_turns_conversation_ready FROM pg_index i WHERE i.indexrelid=to_regclass('assistant_credit_turns_conversation') AND i.indrelid=to_regclass('assistant_credit_turns') AND i.indisvalid AND i.indisready AND i.indisunique=false AND i.indnkeyatts=4 AND i.indnatts=4 AND i.indexprs IS NULL AND (SELECT array_agg(a.attname::text ORDER BY key.n) FROM unnest(i.indkey) WITH ORDINALITY key(attnum,n) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=key.attnum)=ARRAY['user_id','conversation_id','accepted_at','usage_ledger_id']::text[] AND regexp_replace(replace(coalesce(pg_get_expr(i.indpred,i.indrelid),''),'::text',''),'[[:space:]()]','','g')='';
SELECT 1 / count(*)::int AS assistant_usage_calls_receipt_unique_ready FROM pg_index i WHERE i.indexrelid=to_regclass('assistant_usage_calls_receipt_unique') AND i.indrelid=to_regclass('assistant_usage_calls') AND i.indisvalid AND i.indisready AND i.indisunique=true AND i.indnkeyatts=4 AND i.indnatts=4 AND i.indexprs IS NULL AND (SELECT array_agg(a.attname::text ORDER BY key.n) FROM unnest(i.indkey) WITH ORDINALITY key(attnum,n) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=key.attnum)=ARRAY['provider','usage_ledger_id','call_index','receipt_fingerprint']::text[] AND regexp_replace(replace(coalesce(pg_get_expr(i.indpred,i.indrelid),''),'::text',''),'[[:space:]()]','','g')='receipt_fingerprintISNOTNULL';

-- D2 existing-outbox index: same autocommit/invalid-remnant recovery rule.
SET lock_timeout = '5s';
CREATE INDEX CONCURRENTLY IF NOT EXISTS assistant_credit_settlement_outbox_due
 ON outbox_events(next_attempt_at,occurred_at) WHERE event_type='assistant.cost_reconcile' AND published_at IS NULL;
RESET lock_timeout;
SELECT 1 / count(*)::int AS assistant_credit_settlement_outbox_due_ready FROM pg_index i WHERE i.indexrelid=to_regclass('assistant_credit_settlement_outbox_due') AND i.indrelid=to_regclass('outbox_events') AND i.indisvalid AND i.indisready AND i.indisunique=false AND i.indnkeyatts=2 AND i.indnatts=2 AND i.indexprs IS NULL AND (SELECT array_agg(a.attname::text ORDER BY key.n) FROM unnest(i.indkey) WITH ORDINALITY key(attnum,n) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=key.attnum)=ARRAY['next_attempt_at','occurred_at']::text[] AND regexp_replace(replace(coalesce(pg_get_expr(i.indpred,i.indrelid),''),'::text',''),'[[:space:]()]','','g')='event_type=''assistant.cost_reconcile''ANDpublished_atISNULL';
